MERGE INTO topics (topic_id,subject_id,topic_name,description) KEY(topic_id) VALUES (3,1,'Inheritance and Polymorphism','Reuse behaviour with parent classes and flexible method calls');
MERGE INTO topics (topic_id,subject_id,topic_name,description) KEY(topic_id) VALUES (4,1,'Exception Handling','Handle unexpected situations without stopping the program');
MERGE INTO topics (topic_id,subject_id,topic_name,description) KEY(topic_id) VALUES (5,2,'SQL SELECT and WHERE','Retrieve precise data from relational tables');
MERGE INTO topics (topic_id,subject_id,topic_name,description) KEY(topic_id) VALUES (6,2,'Joins and Aggregate Functions','Combine related rows and summarise information');
MERGE INTO learning_material (material_id,topic_id,content) KEY(material_id) VALUES (3,3,'Inheritance lets a child class reuse fields and methods from a parent class. Polymorphism means a parent-type reference can call the correct overridden method for the actual child object.\n\nExample: Student and Admin both extend User.\n\nRevision question: when should a common parent class be used?');
MERGE INTO learning_material (material_id,topic_id,content) KEY(material_id) VALUES (4,4,'An exception is an unusual condition that interrupts normal program flow. Java uses try, catch and finally to handle it.\n\nExample: JDBC code catches SQLException so the application can show a safe error.\n\nRevision question: why should database errors not be shown in detail to users?');
MERGE INTO learning_material (material_id,topic_id,content) KEY(material_id) VALUES (5,5,'SELECT retrieves columns from a table. WHERE filters rows using a condition. ORDER BY sorts the returned rows.\n\nExample: SELECT name FROM users WHERE role = ''STUDENT'' ORDER BY name.\n\nRevision question: which clause limits returned rows?');
MERGE INTO learning_material (material_id,topic_id,content) KEY(material_id) VALUES (6,6,'JOIN combines related tables through matching key values. COUNT, SUM and AVG calculate summaries. GROUP BY makes one summary for each category.\n\nExample: count attempts for each topic using GROUP BY topic_id.\n\nRevision question: why is a JOIN useful for history pages?');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (101,3,'Which keyword establishes inheritance in Java?','MCQ','B',1,'A child class uses extends to inherit from a parent class.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (102,3,'Which is an example of polymorphism?','MCQ','C',1,'A User reference can hold a Student object and call an overridden method.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (103,3,'What does super(...) call?','MCQ','A',1,'super(...) calls a parent constructor.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (104,3,'Method overriding requires:','MCQ','D',1,'An inherited method is redefined with the same signature.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (105,3,'Why use a parent class?','MCQ','B',1,'It keeps shared state and behaviour in one reusable place.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (106,4,'Which block handles an exception?','MCQ','A',1,'A catch block handles a matching exception.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (107,4,'SQLException can occur while:','MCQ','C',1,'It can occur while connecting to or querying a database.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (108,4,'What is the purpose of finally?','MCQ','B',1,'It is commonly used for cleanup that should run whether an error occurs or not.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (109,4,'Which is good error handling?','MCQ','D',1,'Show a friendly message and record technical details safely.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (110,4,'A checked exception must be:','MCQ','C',1,'It must be caught or declared by the method.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (111,5,'Which statement retrieves data?','MCQ','A',1,'SELECT retrieves stored data.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (112,5,'Which clause filters rows?','MCQ','B',1,'WHERE evaluates a condition for each row.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (113,5,'Which operator checks an exact value?','MCQ','D',1,'The equals operator compares an exact value.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (114,5,'ORDER BY name DESC means:','MCQ','C',1,'Rows are sorted by name from Z to A.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (115,5,'What does SELECT * return?','MCQ','B',1,'It returns every column selected from matching rows.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (116,6,'Which keyword combines related tables?','MCQ','A',1,'JOIN combines table rows through a relationship.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (117,6,'Which function counts rows?','MCQ','B',1,'COUNT returns the number of rows or values.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (118,6,'GROUP BY is used to:','MCQ','C',1,'It groups matching values before an aggregate is calculated.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (119,6,'AVG(score) returns:','MCQ','D',1,'AVG calculates the arithmetic average.');
MERGE INTO questions (question_id,topic_id,question_text,question_type,correct_answer,marks,explanation) KEY(question_id) VALUES (120,6,'An INNER JOIN returns:','MCQ','B',1,'It returns rows with matching values in both joined tables.');
